  "category": "其他法术",
  "cost": "可变（参考各法术），1D3点理智值（额外加上见到怪物的损失）",
  "time": "1D6+4轮",
  "en": "CONTACTMONSTERSPELLS",
  "detail": "（除非另有说明）\n\n联络术分为两个独立的部分：和联络神话生物、怪物相关的法术，还有联络神话神祇的法术。后面一部分已经在“通神术”之类。",
