  "time": "1D6+4轮",
  "en": "ContactDeepOne",
  "detail": "本法术须在咸水水体或者海洋边缘施放。要达到最佳效果，施放时要在深潜者城市附近，例如在马萨诸塞州印斯茅斯的海滨，还有英国失落的城镇敦威治镇外的海岸。仪式包含把特别雕刻的石头或珠宝投掷到水里的步骤。",
