  "time": "数分钟",
  "en": "EquilaterialScreen",
  "detail": "本法术只能在幻梦境施放。在施法者面前产生一组复杂的无形几何线条，组成一个完美的深蓝色等边三角形。施法者专注于想要创造的影像，可以让影像浮现。影像从前面看上去是三维可动的，但从后面却看不到，只能显示几何线条。施法者可以随时间改变影像。如果施法者结束专注，影像消散。若施法者连续五分钟无法专注于屏幕，法术终止。",
