  "en": "Eviscerator",
  "detail": "本法术只能在幻梦境施放。这个令人毛骨悚然的法术可以让一团翻滚的黑色锯齿状物体、暗紫色的烟雾和红黄色的能量束击中目标。剜心者撕裂受害者，每在法术中投入8点魔法值，就可以造成1D6点伤害。虽然目标没有任何办法抵御这次攻击，但所有护甲（如果穿着）都能限制伤害。",
