  "cost": "1点魔法值；1D3点理智值",
  "time": "20~60分钟",
  "en": "FindGate",
  "detail": "本法术通过一系列的手势和特殊的歌唱，向施法者显示他直视视野内有无时空门的存在。本法术虽然能够定位时空门，但不可以打开、关闭、创建或通过时空门。而且这种法术受限的形式也无法让施法者得知时空门穿越的是空间还是时间。",
