  "category": "其他法术",
  "cost": "3点魔法值",
  "time": "2轮",
  "en": "FindSerFolk",
  "detail": "告诉施法者最近一个蛇人的方位和距离。极度退化的个体可能因为不被认为是物种的一员而被忽略。法术的最大范围是五英里。许多蛇人巫师都知道本法术，但人类无人知晓，法术也从未被人类文字记载过。",
