  "category": "幻梦境魔法",
  "cost": "可变的魔法值；1+点点理智值",
  "time": "2轮",
  "en": "Flameshield",
  "detail": "本法术只能在幻梦境施放。施法者的手掌前形成一张火焰圆盘。每投入一点魔法值，护盾就拥有一英尺直径。如果护盾生成后再投入魔法值，那么每投入的一点魔法值可以让护盾移动1码。法术“依诺拉停止术”(“索伦白网术”(和“炽天使之耀”(都会被护盾挡开。护盾若触碰任何不由火焰构成的活物时，活物受到1D6点伤害（无视任何护甲）。",
