  "en": "Flight",
  "detail": "创建一种药膏，可以让使用者在空气中飞翔。需要从未受洗礼的小男孩身上提炼的脂肪以及其他可怕的成分，且必须在新月的阴影下用大釜酿造。制成的药膏受到太阳直射就会毁坏，所以必须存放在暗处，而且太阳落山之后才能打开使用。酿造一次可以制成1D4剂药膏。药膏的效力持续1D6小时，可以让使用者以MOV10飞行。",
