  "category": "支配他人",
  "cost": "10+点魔法值，6点理智值",
  "time": "1小时",
  "en": "GatherandChannelFear",
  "detail": "施法者能够产生并引导恐惧，将这些能量转化成魔法值；通常和“梦境发送术”(结合使用，给一定范围内的很多人送去恐怖的噩梦。施法者必须把自己的血（1D4点耐久值）流到某件物品上（通常是神话神祇的塑像），用作施法的中心；施法者觉得这个塑像越恶心，效果就越好。施法者流过血之后，每需要1英里施法半径，就要牺牲10点魔法值。法术的精华就会释放，范围内所有人都要（和施法者）进行成功的人没有效果，但检定失败的人就会做噩梦（如果和“梦境发送术”一起使用）或者杯弓蛇影、情绪紧张、烦躁不安，持续24小时。每有一个人在对抗检定中失败，施法者就能吸收1点魔法值并引导到自己身上，可以用来填补自己的消耗或储存起来以备将来使用——但得到的这些魔法值只能保存到下个新月。",
