  "detail": "耗费别人的美貌增长自己的美貌。法术的目标必须在施法者一英里范围之内，施法者花费一天专注在目标身上并举行所需仪式。到午夜时分，最后的仪式完成时，施法者和目标进行一次POW对抗检定：若施法者胜出，目标失去10点APP（这会让他衰老），施法者增加5点APP（这会让他变年轻）。如果目标在对抗检定中胜出，施法者会昏迷1D3天并永久失去5点CON。多数情况下，法术的目标并不会意识到变化。深层魔法：如果支付双倍或三倍的消耗，施法者可以增加损失和得到的APP（双倍消耗时，目标失去20点APP，施法者获得10点APP，以此类推）。注意施法者一旦在POW对抗检定中落败，昏迷会持续2D3+1天，并失去20点CON。",
