  "en": "GoodThiefWater",
  "detail": "这是种保护施法者的财产不被偷盗的法术。施法者用多种材料准备一剂浸出液，将它洒在物品上。尝试盗取这件物品的人必须通过极难难度的检定才能狠心下手。否则，这个“贼”会莫名其妙地对物品产生强烈的厌恶，在思考这次盗窃时还会轻微地恶心。效果持续1D6+1轮。浸出一剂能保护一件足有普通汽车大小的物品。KP裁定：可能需要「克苏鲁神话」「神秘学」或「艺术/手艺（药剂）」检定来确保炼制按照正确的步骤进行。深层魔法：若额外消耗10点魔法值和1D4+4点理智值，浸出液会更加强力（用量会减少，最多能保护四件物品）。如果洒上了它，“贼”一旦接近物品就会惊厥；他必须在CON检定中成功，否则只能在地上翻滚，什么也做不了，直到他们被抬走或者物品被移走为止。",
