  "detail": "可怕的碾压般的压力定住一个或多个目标，暂时抽取他们的STR。法术的范围是10码，可以同时作用于多人；但是，每多一个目标，维持法术时每分钟就要额外消耗2D6点魔法值——只要施法者有足够的魔法值消耗，法术想持续多少分钟就能持续多少分钟，不需要额外的理智值消耗，但是施法者必须全程专注施法。施法者须和目标进行一次对抗检定并胜出，法术才能生效：若施法者胜出，目标会感到巨大的压力从天而降，身体无法动弹——好像被伟大的克苏鲁的强悍的触手捆住一样。法术每持续一分钟，目标就要暂时失去5D10点STR。若目标的STR减少到0以下，他将昏迷。",
