  "en": "GraveyardKiss",
  "detail": "本法术需要一具人类尸体。尸体要具有足够的筋肉支持它复苏后的活动能力。施法者将一盎司（约28克）自己的血液注入尸体的口中，然后亲吻尸体的嘴唇，“将自我的一部分呼入”尸体当中。施法者失去5点作为给尸体的赠予。如果施法成功，施法者可以对僵尸下达一些它能做到的命令。随着时间推移，僵尸可能会掌握更复杂的指令。一旦施法者死亡，僵尸会停止活动并腐烂。僵尸会存在到它解体为止（这需要很多年）。祈祷的一部分集中涉及到神话神神祇——但是不使用特定的名字。",
