  "en": "GreatRiteofSacrifice",
  "detail": "这种仪式靠程序性地杀死一个人来向施法者提供魔法值和者以人祭为中心施展一系列复杂的仪式，然后用附过魔的刀杀死不幸的受害者。如果魔法值被给予施法者，施法者的魔法值点数会直接增加；但如果24小时之内不使用，超出的点数都会消失。靠本仪式得到的魔法值不能超过施法者正常最大魔法值的两倍。施法者还可以获得受害者的而非魔法值，最多可以获得受害者的一半。这些必须在一个小时之内用掉，否则就会消失。神祇会得到施法者所愿的报酬——多数时候，神也会因施法者的布施而回赠他一些恩惠。",
