  "en": "ImThrow",
  "detail": "背诵一小段韵文，施法者或受术者就能投掷一个物体并恰好落在50尺之内他预想的位置。法术引导投掷物的轨迹，让它击中预期的目标。每次施法可以作用于一个投掷物。",
