  "en": "StealLife'sBlood",
  "detail": "允许让施法者用人祭的方式来复活死者。施法者必须在和将在法术中牺牲的其中一人进行POW对抗检定并胜出：若施法者落败，受害者将毫发无损，施法者反而要受到1D10点伤害。若施法者胜出，所有人祭的血液都会离开身体，汇聚成球，漂浮在身体上方。当所有祭品的血液都吸收完毕后（需要1D6轮），它会从空中飞流到（由施法者准备好）等待复活的尸体内外。1D6分钟内尸体就会重生。目击此仪式需要进行理智检定（损失1/1D6点）。法术主要的副作用是，复生的尸体将永无休止地渴求活物的鲜血。",
