  "detail": "这种魔法攻击会扩张目标的脑组织，造成剧烈疼痛。目标必须在施法者视野范围内，且施法者必须和目标进行一次POW检定并胜出。若成功，目标的耳鼻眼会开始流血——感觉就像他们的大脑即将爆炸。目标还会受到1D3点伤害。法术可以延长，施法者要专注于目标（不理会其他所有事情），每延长一轮额外消耗3点魔法值。还有可能造成永久脑损伤。如果维持法术达到三轮（包括此后每满三轮），目标就必须进行一次POW检定；若失败，目标永久损失5点INT。如果目标的耐久值因此归零，他们的大脑将液化，发出令人作呕的咯吱声，变成灰白色的脓浆流出耳朵和鼻孔——目击这一恐怖情景会引发理智检定（损失0/1D4点）。",
