  "detail": "允许施法者不用动口，直接和其他的人精神进行交流。施法者最多可以和三个人交流，他们必须在视野范围内（这交流是单向的，从施法者到接收者）。也可以再增加接收者，每额外消耗1点理智值和1点魔法值就能增加三个接收者。法术持续2轮（额外消耗2点魔法值可以延长）。有一个不幸的副作用，如果法术生效期间施法者失去了理智值，那么和施法者保持精神联系的人都会直接受到同样的理智值损失（自动损失理智值）。深层魔法：如果施法者对预定的目标非常了解（私交甚久），那么心灵感应将不受视野限制。这种情况下法术只能同时影响一个目标。",
