  "en": "TemporalRip",
  "detail": "将目标扯出时空。其他人会看到目标被定住，四周包裹着锯齿状的黑暗，从黑暗中可以看到宇宙的虚空，还有早已熄灭的古老星体已经死亡的光芒。目标必须在施法者视野范围内，施法者需要做出手势并诵念已死的异界神名。施法者只要保持专注并持续打出手势就可以维持法术，无需额外消耗（如果专注和手势被打断，法术终止）。其他人能看到目标被锁定在星光黑暗之中，但不能触碰，也无法与其互动（目标的形象可以被认为是在现实结构中留下的后像——法术终止后目标才实际返回）。目标被释放后会返回通常时空，感觉不适并虚弱1D4轮（所有技能检定和属性检定都获得一颗惩罚骰），并且移动速率减半。目标不能回想他们在时空之外的经历，也不知道有多少时间已经经过。不要对玩弄宇宙的结构掉以轻心。施法者和不幸的目标都可能无意中吸引廷达洛斯猎犬的注意：每当施放法术时，施法者和目标就有1%的概率被猎犬同时发现。同一巫师每施放本法术一次，吸引到猎犬的概率就增加1%。",
