  "en": "TimeGate",
  "detail": "创建一道通向过去或未来的时空门。本法术和“时空门创建术”类似，但是消耗的POW与穿越的年数而非旅行的里程相关。使用“时光门创建及旅行消耗”表作为指导来决定POW和魔法值消耗（KP可以根据需求调整数值）。本法术定位的时刻只能和预计的近似相同，但时光门创建之后，“这时”和“那时”之间的时间会精确地保持不变。深层魔法：巫师通过邪恶的记号和吟唱，可以创建多路径的时光门——这样一道时光门可以通向不止一个遥远时代。在通过时空门时，只有施法者清楚哪条路通往哪个时代。那些蠢到没有施法者帮助就通过时空门的人将无法分辨正确的路径，会抵达时空门通向的任意地点（随机决定）。时光门的创建过程不变。",
