  "time": "6小时",
  "en": "TimeTrap",
  "detail": "将一个生物或人穿越时光传送到施法者面前。仪式需要6小时不间断的冥想和大量人血。施法者施法时必须将目标以正常的设定形象化——对于过去或未来的生物，则需要施法者有办法使用观测未来或过去的设备。施法者和目标进行POW对抗检定：若施法者胜出，捕捉到的生物就会在施法者五里之内的任一地点出现，且总会在地面上。此时目标是自由的，可以任意行动，但被困在新时间当中。需要异界大气或者缺少其他条件的生物可能死去而来不及得到恢复。法术是单向的。被困的生物不能用本法术上溯或下延时间。每次施法只能困住一只生物。法术只能在时间中施放，不能穿越异维度。",
