  "en": "ViewGate",
  "detail": "本法术在可疑的“时空门”处施放时，允许施法者不必通过时空门就知道时空门另一端有没有东西、有什么东西。观察时的消耗是可变的，等于时空门魔法值消耗的一半（向上取整）。所以一道需要8点魔法值来通过的时空门，观察时需要4点魔法值和4点理智值。视野将维持1D6+1轮。如果视野中有恐怖的东西，每位观察者都要付出额外的理智值作代价。观察者可以尝试合适的技能检定来了解他观察的是何地、何时、何物。",
