  "time": "4轮",
  "en": "ViridianWind",
  "detail": "本法术只能在幻梦境施放。一阵绿色半透明的轻风从施法者处刮向目标地点，距离最多30码，刮风范围直径3码。此风刮过路径上一切东西都会凝结成固体，包括无法脱身的活物。凝结过程需要2D6轮来完成，所以生物可以（如果可能的话）在凝结成固体之前离开效果范围。因为这是梦境，所以KP可以自行决定凝结的人是活着（能被解冻）还是死亡。",
