  "detail": "暂时提升施法者的APP和某些有关技能。需要一场仪式，在仪式上焚烧各种施法成分。接下来的24小时中，法术为施法者增加5D10点APP，且施法者的「魅惑」「话术」和「说服」检定增加一颗奖励骰。深层魔法：可以逆向施放本法术，在24小时中，目标减少5D10点APP、损失1D4点理智值，「魅惑」「话术」和「说服」检定增加一颗惩罚骰。",
