  "en": "VoiceThoughts",
  "detail": "允许施法者将他人的想法有声化，且不从嘴中说出，而是从附近（20尺内）的其他地方发出。每四句话需要消耗1点魔法值和1点理智值。通常用来扰乱或迷惑敌人；目标必须进行一次困难INT检定并成功否则就会被声音打扰（如处于战斗等紧急状况中，下次行动可能得到一颗惩罚骰）。",
