  "category": "幻梦境魔法",
  "cost": "8+点魔法值；1D3点理智值",
  "time": "2轮",
  "en": "Whirligig",
  "detail": "本法术只能在幻梦境施放。带着黑线的旋转狂风吹起目标，将他们转到空中——除非他们和施法者进行一次POW检定并胜出。施法者每额外消耗1点魔法值，吹飞的高度就可以升降10尺。当法术终止时，目标会坠落并受到坠落伤害；不论如何他们都会头晕目眩，接下来的1D6轮中无法站立或行动，除非目标进行一次极难DEX检定并成功，每轮可以尝试一次。维持法术每轮需要消耗8点魔法值。法术范围是10尺。",
