  "category": "交流魔法",
  "cost": "3+ 点魔法值；1D6 点理智值",
  "time": "10+ 分钟",
  "en": "Words of Power",
  "detail": "施法者与大群听众创造强烈的联系。施法者必须即兴演讲并看似真诚，来维持听众的注意力。施法者在讲到每个论据、论点和命令时都要消耗3 点魔法值并进行一次 KP 认为合适的社交检定（「魅惑」「话术」或「说服」）并成功，不然演讲会在困惑不解中犹犹豫豫地结束。在演讲成功结束后，听众会在 1D3 天中完全相信演讲的内容。",
