  "desc": "(Pnakotica)：\n\n这本著作只存在于传说之中，是写在纸草卷轴上的希腊语版，据说包含的信息能与《死灵之书》匹敌。它应该是从伊斯语版翻译过来的。\n\n理智值丧失：1d8/2d8。“克苏鲁神话”技能＋15%。读解平均所需时间：52周。浏览平均所需时间：104小时。\n\n咒文：接触有翼者（即“接触远古者”）。"
