  "mythos": "10%",
  "spells": "召来暗黑之子（即“召唤/控制纳伽埃”）、丧者的复活（即“创造僵尸”）、接近坟墓之子（即“接触食尸鬼”）、解放等待的黑暗（即“召唤/送离塞埃格”）、灵魂吸取（即“吸收精神力”）、对话等待的黑暗（即“接触塞埃格”）。",
  "desc": "这个版本只印刷了极少的数量就立即被教会和国家查禁，现在据信只剩两本留存。这两本书一直被锁在德国的图书馆里，直到1930年代纳粹的阴影笼罩德国。没人知道这两本书到底是进了焚书的柴堆还是成了某位纳粹高官的收藏品，自二战结束之后它们就下落不明。\n\n理智值丧失：1d6/2d6。“克苏鲁神话”技能＋10%。读解平均所需时间：44周。浏览平均所需时间：80小时。\n\n咒文：召来暗黑之子（即“召唤/控制纳伽埃”）、丧者的复活（即“创造僵尸”）、接近坟墓之子（即“接触食尸鬼”）、解放等待的黑暗（即“召唤/送离塞埃格”）、灵魂吸取（即“吸收精神力”）、对话等待的黑暗（即“接触塞埃格”）。"
