  "spells": "仙砂还魂箓（即“死者复活术”） 卷二：仪式性的食尸及食尸鬼信仰 咒文：接触食尸鬼 卷三：天鬼 咒文：摄魔拘鬼箓（即“召唤/控制拜亚基”） 卷四：地鬼及其与地震的关系 咒文：地罡考召箓（即“接触钻地魔虫”） 卷五：中国南海沿岸的深潜者及其人类信徒；时间与空间；廷达洛斯猎犬与辽丹 咒文：接触廷达洛斯猎犬 卷六：位于中亚的冷原及未知的卡达斯 咒文：幻界步灵升箓（即“卡达斯之门”） 卷七：奈亚拉托提普及其无数形态；拉莱耶的上浮与克苏鲁的再临；身为起始与终结的阿撒托斯；神灵及生物的理想形态——将各种神格存在和生物按照官僚体系排列的官阶序列 咒文：接触奈亚拉托提普。",
  "desc": "非常准确的版本，接近完美，有着强大的力量。\n\n理智值丧失：1d4/1d8。“克苏鲁神话”技能＋8%。读解平均所需时间：40周。浏览平均所需时间：80小时。\n\n卷一：关于黄帝的业绩，他令人惊叹的发明与医术\n\n咒文：仙砂还魂箓（即“死者复活术”）\n\n卷二：仪式性的食尸及食尸鬼信仰\n\n咒文：接触食尸鬼\n\n卷三：天鬼\n\n咒文：摄魔拘鬼箓（即“召唤/控制拜亚基”）\n\n卷四：地鬼及其与地震的关系\n\n咒文：地罡考召箓（即“接触钻地魔虫”）\n\n卷五：中国南海沿岸的深潜者及其人类信徒；时间与空间；廷达洛斯猎犬与辽丹\n\n咒文：接触廷达洛斯猎犬\n\n卷六：位于中亚的冷原及未知的卡达斯\n\n咒文：幻界步灵升箓（即“卡达斯之门”）\n\n卷七：奈亚拉托提普及其无数形态；拉莱耶的上浮与克苏鲁的再临；身为起始与终结的阿撒托斯；神灵及生物的理想形态——将各种神格存在和生物按照官僚体系排列的官阶序列\n\n咒文：接触奈亚拉托提普。"
