  "desc": "考古学家哈罗德·哈德里·库普兰德教授（参见《赞苏石板》的介绍）拥有一本密斯卡托尼克大学出版社于1907年出版的注释版《波纳佩教典》，库普兰德当时刚刚开始探查关于克苏鲁崇拜的事情，那时他似乎尚未接触穆大陆的石板或霍格的原稿，认为它们没有翻译的价值。\n\n理智值丧失：1d3/1d6。“克苏鲁神话”技能＋6%。读解平均所需时间：13周。浏览平均所需时间：26小时。\n\n咒文：只有霍格的手写原稿和穆大陆的文书中才载有咒文。其中有：接触深潜者、接触父神达贡、接触母神海德拉。最初出版的版本描述了崇拜的仪式，但没有必要的细节。在库普兰德的注释版中，编辑设法重构了“接触深潜者”的咒文，而其余的则遗失了。\n\n其它利益及效果：读者可进行“人类学”及“神秘学”检定。发现霍格原稿抄本的人会同时发现他的翻译笔记，研究笔记的读者可以获得“神话语言：纳卡尔文”的基础技能，起始数值为[1d6＋1%]。"
