  "desc": "带作者边注的书：\n\n这本书十分有趣，是作者的后代惠普尔·菲利普斯(Whipple Phillips)［译注：影射洛夫克拉夫特的祖父］的藏书之一，此人是居住在罗德岛州普罗维登斯市的商人。书中有作者亲笔写下的注解和订正，只要看到这些注解就能明白，在作者过去以为是传说或民间故事之类的东西里其实包含着恐怖的事实。书头和书尾留白的纸上记载了各种仪式，其中含有数种咒文。\n\n理智值丧失：1d6/1d10。“克苏鲁神话”技能＋7%。读解平均所需时间：14周。浏览平均所需时间：28小时。\n\n咒文：只有这本书上载有咒文，是菲利普斯牧师亲自用细长的笔迹写下的。其中有：召唤/送离伊塔卡（即伊塔库）、接触纳尔拉托（即奈亚拉托提普）、接触撒多格瓦（即撒托古亚）、接触犹盖·索斯约特（即犹格·索托斯）、旧印。\n\n其它利益及效果：阅读这本书的读者可进行“历史”及“神秘学”的检定。"
